#include "audit_arithmetic.hpp"
int main(int argc,char** argv){try{
    using namespace audit;
    require(argc==4,"usage: tangent_traces BASELINE.json MODEL.json OUTPUT.json");auto data=read_json(argv[1]),model=read_json(argv[2]);std::vector<Term> terms;for(const auto& item:model.at("terms").arr){const auto& e=item.at("exponents").arr;terms.push_back({e[0].integer(),e[1].integer(),Big(item.at("coefficient").scalar)});}std::vector<Point> base,images;for(const auto& q:data.at("projected_base").arr)base.push_back(read_point(q));for(const auto& q:data.at("images").arr)images.push_back(read_point(q.at("point")));require(base.size()==225&&images.size()==226,"frozen counts");Point kappa;Row canonical(base.size());for(const auto& q:data.at("pool").at("split_fibers").arr[0].at("point_indices").arr){size_t i=size_t(q.integer());kappa=plus(kappa,images.at(i));const auto& a=data.at("images").arr[i];int j=a.at("projected_index").integer();if(j>=0)canonical.at(size_t(j))+=a.at("sign").integer();}Matrix old;for(const auto& sparse:data.at("rows").arr){Row row(base.size());for(const auto& a:sparse.arr)row.at(size_t(a.arr[0].integer()))=Big(a.arr[1].scalar);old.push_back(row);}require(matrix_rank(old)==6,"baseline rank6");Matrix all=old;
    audit::SSL ssl;auto sk=ssl.make(kappa),twice=ssl.make({}),trace=ssl.make({});size_t split=0,irreducible=0,repeated=0,exceptions=0,alias_count=0;std::map<std::string,std::vector<int>> trace_keys;std::ofstream out(argv[3]);require(bool(out),"fresh trace output");out<<"{\"standing\":\"producer-unverified\",\"scope\":\"226-frozen-tangent-residual-traces\",\"tangents\":[";
    for(size_t i=0;i<images.size();++i){const auto& point=data.at("pool").at("points").arr.at(i);CP origin{Big(point.at("x").scalar),Big(point.at("y").scalar)};require(evaluate(terms,origin)==0,"frozen curve point");auto l=normalize({evaluate(terms,origin,1,0),evaluate(terms,origin,0,1),0});l[2]=mod(-l[0]*origin.x-l[1]*origin.y);Poly restriction(5);for(const auto& t:terms){auto q=product(ppow({origin.x,l[1]},t.x),ppow({origin.y,mod(-l[0])},t.y));for(size_t j=0;j<q.size();++j)restriction[j]=mod(restriction[j]+t.c*q[j]);}trim(restriction);auto residual=divide(divide(restriction,0),0);require(product({0,0,1},residual)==restriction,"all tangent product reconstructions");std::string category="affine-degree-exception";Big disc=0;
        if(residual.size()==3){disc=mod(residual[1]*residual[1]-4*residual[0]*residual[2]);Big e=(p-1)/2,value;mpz_powm(value.get_mpz_t(),disc.get_mpz_t(),e.get_mpz_t(),p.get_mpz_t());auto dd=bn(disc),ee=bn(e),pp=bn(p),expected=bn(value);BN answer(BN_new());require(BN_mod_exp(answer.get(),dd.get(),ee.get(),pp.get(),ssl.context.get())==1&&BN_cmp(answer.get(),expected.get())==0,"all independent Euler criteria");if(value==0){category="repeated-contact";++repeated;}else if(value==1){category="split-distinct-rational";++split;}else{require(value==p-1,"Euler nonresidue");category="irreducible-quadratic";++irreducible;}}
        else ++exceptions;
        Point t=plus(kappa,negative(plus(images[i],images[i])));auto image=ssl.make(images[i]);require(EC_POINT_dbl(ssl.group.get(),twice.get(),image.get(),ssl.context.get())==1&&EC_POINT_invert(ssl.group.get(),twice.get(),ssl.context.get())==1&&EC_POINT_add(ssl.group.get(),trace.get(),sk.get(),twice.get(),ssl.context.get())==1&&ssl.encode(trace.get())==key(t),"all independent aggregate traces");trace_keys[key(t)].push_back(int(i));std::vector<Row> rows;
        auto alias=[&](int j,int sign){Row row=canonical;for(auto& x:row)x=-x;const auto& projection=data.at("images").arr[i];int k=projection.at("projected_index").integer();if(k>=0)row.at(size_t(k))+=2*projection.at("sign").integer();if(j>=0)row.at(size_t(j))+=sign;require(row_sum(row,base).zero,"tangent trace alias row sum");rows.push_back(row);all.push_back(row);++alias_count;require(alias_count<=4096,"alias cap");};
        if(residual.size()==3){if(t.zero)alias(-1,0);else for(size_t j=0;j<base.size();++j){if(t==base[j])alias(int(j),1);if(t==negative(base[j]))alias(int(j),-1);}}
        if(i){out<<',';}out<<"{\"point_index\":"<<i<<",\"category\":\""<<category<<"\",\"line\":";emit_poly(out,Poly(l.begin(),l.end()));out<<",\"restriction\":";emit_poly(out,restriction);out<<",\"residual\":";emit_poly(out,residual);out<<",\"discriminant\":\""<<disc<<"\",\"trace\":{\"infinity\":"<<(t.zero?"true":"false");if(!t.zero)out<<",\"x\":\""<<t.x<<"\",\"y\":\""<<t.y<<'"';out<<"},\"alias_rows\":[";for(size_t j=0;j<rows.size();++j){if(j)out<<',';emit_row(out,rows[j]);}out<<"]}";
    }
    size_t collisions=0;for(const auto& bucket:trace_keys)if(bucket.second.size()>1)collisions+=bucket.second.size()-1;out<<"],\"split_distinct_rational\":"<<split<<",\"irreducible_quadratic\":"<<irreducible<<",\"repeated_contact\":"<<repeated<<",\"affine_degree_exceptions\":"<<exceptions<<",\"aggregate_trace_collisions\":"<<collisions<<",\"alias_rows\":"<<alias_count<<",\"baseline_rank\":6,\"union_rank\":"<<matrix_rank(all)<<",\"all_independent_trace_checks_agree\":true,\"all_independent_Euler_checks_agree\":true,\"new_curve_points\":0}\n";require(bool(out),"complete trace result");
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
